import{_ as o,o as c,c as a,a3 as d}from"./chunks/framework.CRbjHCyB.js";const u=JSON.parse('{"title":"源码概览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/clice/design/overview.md","filePath":"zh/clice/design/overview.md"}'),i={name:"zh/clice/design/overview.md"};function r(l,e,s,n,t,p){return c(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="源码概览" tabindex="-1">源码概览 <a class="header-anchor" href="#源码概览" aria-label="Permalink to &quot;源码概览&quot;">​</a></h1><p>本文档介绍 clice 源码中各模块的职责与定位，帮助读者建立对整个项目结构的整体认知。关于每个模块的详细设计，请参阅对应的专题文档。</p><h2 id="项目愿景" tabindex="-1">项目愿景 <a class="header-anchor" href="#项目愿景" aria-label="Permalink to &quot;项目愿景&quot;">​</a></h2><p>clice 是一个全新的 C++ 语言服务器，从架构层面重新设计，旨在解决以往 C++ 语言服务器长期存在的问题。主要特点：</p><ul><li><p><strong>编译上下文</strong>：clice 是首个将编译上下文作为正式概念引入的语言服务器。编译、索引和查询的每个步骤都会明确区分当前的编译上下文，用户可以查询和切换这些上下文。详见 <a href="./compilation-context">编译上下文</a>。</p></li><li><p><strong>多进程架构</strong>：master + worker 进程模型将 Clang 的内存泄漏和崩溃隔离开来，同时支持感知优先级的调度和实时内存监控。详见 <a href="./multi-process">多进程架构</a>。</p></li><li><p><strong>协程异步模型</strong>：基于 C++20 协程和 kotatsu 库，取代传统的回调式异步，使业务逻辑更清晰。</p></li><li><p><strong>统一编译调度</strong>：每个高开销的构建产物——Preamble PCH、C++20 模块 PCM、文档 AST、一次性批处理运行——都是统一编译任务图中的一个节点，支持构建共享、实时协作式取消和感知依赖关系的失效处理。详见 <a href="./task-graph">编译任务图</a>。</p></li></ul><h2 id="模块概览" tabindex="-1">模块概览 <a class="header-anchor" href="#模块概览" aria-label="Permalink to &quot;模块概览&quot;">​</a></h2><h3 id="src-support-—-基础工具库" tabindex="-1"><code>src/support/</code> — 基础工具库 <a class="header-anchor" href="#src-support-—-基础工具库" aria-label="Permalink to &quot;`src/support/` — 基础工具库&quot;">​</a></h3><p>供其他所有模块共享的通用工具和基础设施。</p><ul><li><code>CacheStore</code>：面向文件型构建产物（PCH/PCM 等）的磁盘制品存储——成对原子提交、命名空间配额、LRU 淘汰和崩溃恢复。</li><li><code>FuzzyMatcher</code>：用于代码补全和符号搜索的 Token 感知模糊匹配。</li><li>Markup / Doxygen：文档注释的解析与格式化。</li><li>日志、文件系统抽象、字符串工具等。</li></ul><h3 id="src-vfs-—-文件标识与版本" tabindex="-1"><code>src/vfs/</code> — 文件标识与版本 <a class="header-anchor" href="#src-vfs-—-文件标识与版本" aria-label="Permalink to &quot;`src/vfs/` — 文件标识与版本&quot;">​</a></h3><ul><li><code>FileTable</code>：将文件路径映射为全系统使用的稳定 <code>Fid</code> 标识，并管理据此得到的各文件共享信息——stat 标记、内容版本、扫描结果和目录列表。两层时效性检查（先走 stat 快速路径，再计算内容哈希并修复 stat 标记）集中实现在此处，供所有使用方共享：PCH 验证、索引过期判断和磁盘轮询。</li></ul><h3 id="src-config-—-配置" tabindex="-1"><code>src/config/</code> — 配置 <a class="header-anchor" href="#src-config-—-配置" aria-label="Permalink to &quot;`src/config/` — 配置&quot;">​</a></h3><ul><li><code>Config</code>：加载并合并 <code>clice.toml</code> 与 LSP <code>initializationOptions</code>，严格校验未知键，并包含用于生成配置文档的 JSON schema。</li></ul><h3 id="src-command-—-编译命令处理" tabindex="-1"><code>src/command/</code> — 编译命令处理 <a class="header-anchor" href="#src-command-—-编译命令处理" aria-label="Permalink to &quot;`src/command/` — 编译命令处理&quot;">​</a></h3><p>从编译数据库（CDB）读取的命令是构建系统生成的原始命令，不能直接交给 Clang 前端——它们可能包含仅用于代码生成的选项、缺少系统头文件搜索路径，或者包含与语言服务器无关的参数。本模块只需解析每条命令一次，即可将其转换为供系统其余部分使用的结构化形式。</p><ul><li><code>CompilationDatabase</code>：加载 <code>compile_commands.json</code>，将每个条目解析一次，转换为由稳定 <code>ConfigID</code> 标识的、经过驻留和分类的参数结构。在此基础上，它会应用用户配置规则，为没有条目的文件合成备用命令，推导输入语言，计算条目标识哈希，并按需生成 driver 或 <code>-cc1</code> 命令行。</li><li><code>Toolchain</code>：查询系统编译器以获取隐式编译参数（例如系统头文件搜索路径），并采用两层缓存——按 driver 调用形式缓存探测结果，按输入类型缓存合成的选项集。</li><li><code>SearchConfig</code>：头文件搜索路径的四层模型（Quoted / Angled / System / After），与 Clang 内部的搜索逻辑一致。</li></ul><p>详见 <a href="./command-resolve">编译命令解析</a>。</p><h3 id="src-compile-—-编译抽象" tabindex="-1"><code>src/compile/</code> — 编译抽象 <a class="header-anchor" href="#src-compile-—-编译抽象" aria-label="Permalink to &quot;`src/compile/` — 编译抽象&quot;">​</a></h3><p>封装 Clang 编译器，将 Clang API 抽象为安全、统一的编译接口。这一层是纯粹的编译抽象，不包含任何服务器逻辑。</p><ul><li><code>CompilationUnit</code> / <code>CompilationUnitRef</code>：Clang AST 上下文的 RAII 封装。<code>CompilationUnitRef</code> 提供统一的只读视图，可用于访问源位置映射、预处理器指令、AST 节点等。它是 <code>src/feature/</code> 和 <code>src/semantic/</code> 的主要输入。</li><li><code>CompilationParams</code>：描述单次编译的完整配置，包括编译类型（Preamble / Content / Completion / Indexing 等）、文件重映射、PCH/PCM 复用等。</li><li>在编译期间收集诊断信息和 clang-tidy 结果。</li></ul><h3 id="src-syntax-—-轻量级语法处理" tabindex="-1"><code>src/syntax/</code> — 轻量级语法处理 <a class="header-anchor" href="#src-syntax-—-轻量级语法处理" aria-label="Permalink to &quot;`src/syntax/` — 轻量级语法处理&quot;">​</a></h3><p>无需完整 AST 的语法级处理。在编译前运行，可快速获取文件的结构信息和依赖关系。</p><ul><li><code>Lexer</code>：基于 Clang 原始词法分析器构建的 Token 级工具。不运行预处理器。用于扫描指令、解析 include 路径等。</li><li><code>DependencyGraph</code>：全局 include/模块依赖图，支持正向查询、反向查询、宿主源文件搜索、include 链查找等。</li><li>依赖扫描：封装 Clang 的 <code>DependencyDirectivesScanner</code>，快速提取 include 和模块依赖</li><li><code>IncludeResolver</code>：根据搜索路径配置将 include 路径解析为实际文件</li><li>Preamble 合成：构建前缀/后缀文件，使头文件能够在其宿主文件的预处理器状态下编译</li></ul><p>详见 <a href="./dependency-scanning">依赖扫描</a>。</p><h3 id="src-semantic-—-语义分析" tabindex="-1"><code>src/semantic/</code> — 语义分析 <a class="header-anchor" href="#src-semantic-—-语义分析" aria-label="Permalink to &quot;`src/semantic/` — 语义分析&quot;">​</a></h3><p>提供 Clang 原生 API 之外的语义分析能力。以 <code>CompilationUnitRef</code> 为输入，提取更高层次的语义信息。</p><ul><li><code>Semantics</code>：统一语义映射——每次编译仅遍历一次 AST，记录所有相关节点及其 Token 归属；选择、功能投影和索引生成都是对该映射的纯查询，而无须分别遍历 AST</li><li><code>TemplateResolver</code>：通过伪实例化解析依赖名，使语义分析能够透视模板上下文。详见 <a href="./template-resolver">模板解析器</a>。</li><li><code>SymbolKind</code> / <code>RelationKind</code>：细粒度的符号种类和关系类型</li></ul><h3 id="src-index-—-符号索引" tabindex="-1"><code>src/index/</code> — 符号索引 <a class="header-anchor" href="#src-index-—-符号索引" aria-label="Permalink to &quot;`src/index/` — 符号索引&quot;">​</a></h3><p>支持跨翻译单元查询的符号索引系统。层次结构如下：</p><ul><li><code>TUIndex</code>：单次编译产出的索引行，从语义映射投影而来</li><li><code>ProjectIndex</code>：全局层——包含外部可见符号，以及翻译单元与其所贡献文件之间的对应记录</li><li><code>Shard</code>：以文件为单位的存储单元。每个以不同方式预处理该文件的编译上下文都会产生一个变体，这些变体根据其编码行的内容标识去重；文件局部名称保存在分片本身，只有外部名称会进入 <code>ProjectIndex</code></li><li><code>BlobDatabase</code>：持久化后端——所有索引 blob 都存放在单个 LMDB 数据库中</li></ul><p>详见 <a href="./symbol-index">符号索引</a>。</p><h3 id="src-feature-—-lsp-功能实现" tabindex="-1"><code>src/feature/</code> — LSP 功能实现 <a class="header-anchor" href="#src-feature-—-lsp-功能实现" aria-label="Permalink to &quot;`src/feature/` — LSP 功能实现&quot;">​</a></h3><p>LSP 功能的具体实现。每个功能接收 <code>CompilationUnitRef</code>，返回对应的 LSP 响应数据。这一层是纯粹的计算层，不涉及网络通信、状态管理或进程调度。</p><p>包括：代码补全、悬停信息、签名帮助、语义高亮、内联提示、文档符号、文档链接、折叠范围、格式化、诊断等。</p><blockquote><p><code>feature/</code> 仅涵盖单文件、基于 AST 的功能实现。跨文件代码导航功能（转到定义、查找引用等）由服务器的 <code>service/</code> 层（<code>Features</code>/<code>IndexQuery</code>）通过索引数据提供。部分功能涉及多阶段处理——例如，代码补全中的 include 路径补全无需完整编译即可在语法层处理。</p></blockquote><h3 id="src-sched-—-编译调度核心" tabindex="-1"><code>src/sched/</code> — 编译调度核心 <a class="header-anchor" href="#src-sched-—-编译调度核心" aria-label="Permalink to &quot;`src/sched/` — 编译调度核心&quot;">​</a></h3><p>任务图引擎，负责决定构建哪些内容、何时构建，并共享构建结果。</p><ul><li><code>TaskGraph</code>：共享构建图。每个计算开销较大的产物都是一个节点；对同一节点的并发请求会汇入同一轮构建，避免重复工作；取消采用协作式机制；图中的边会按依赖关系驱动失效处理</li><li><code>PCHFamily</code> / <code>PCMFamily</code> / <code>TURunFamily</code>：分别用于 Preamble PCH（以内容为键）、C++20 模块 PCM（包含导入边和提供方跟踪）以及索引与 lint 共用的一次性翻译单元运行的节点族</li><li><code>Workspace</code>：以磁盘状态为准的聚合体——包含编译数据库、依赖图、产物注册表和项目索引。核心不变量：打开文件中未保存的缓冲区内容绝不会修改 <code>Workspace</code>；它只反映磁盘上的状态</li><li><code>ContextResolver</code>：解析文件编译时采用的编译命令和包含方上下文，并负责头文件上下文判定、用户上下文选择和 Preamble 合成</li><li><code>IndexStore</code> / <code>IndexPump</code>：前者负责索引持久化事务（合并、保存、与 CDB 协调），后者是后台调度器，通过 worker 处理需要更新的文件，并采用感知前台负载的预算机制</li><li>引导与批处理驱动程序：负责服务器的冷启动编排，以及 <code>clice index</code> / <code>clice lint</code> 所使用的无头执行模式</li></ul><h3 id="src-worker-—-worker-进程" tabindex="-1"><code>src/worker/</code> — Worker 进程 <a class="header-anchor" href="#src-worker-—-worker-进程" aria-label="Permalink to &quot;`src/worker/` — Worker 进程&quot;">​</a></h3><ul><li><code>WorkerPool</code>：管理 worker 进程的生命周期与调度——在崩溃预算约束下启动、监控和重新拉起进程，并在冷却后恢复；基于文档亲和性安排有状态任务；通过优先级队列和感知前台负载的容量管理分发无状态任务</li><li><code>StatefulWorker</code>：持有文档 AST 并响应查询请求</li><li>无状态 worker 执行一次性任务（PCH/PCM 构建、代码补全、格式化、索引任务）</li></ul><h3 id="src-server-—-服务器运行时" tabindex="-1"><code>src/server/</code> — 服务器运行时 <a class="header-anchor" href="#src-server-—-服务器运行时" aria-label="Permalink to &quot;`src/server/` — 服务器运行时&quot;">​</a></h3><p>语言服务器的核心运行时，负责将上述各层组装成可运行的服务。</p><p><strong><code>protocol/</code></strong> — 协议定义。描述主进程与 worker 进程之间以及服务器与客户端之间通信所用的消息格式。包括 Worker 协议（编译/查询/构建请求）、LSP 扩展协议（编译上下文切换等），以及面向 AI agent 的 agentic 协议。</p><p><strong><code>state/</code></strong> — 文档状态与失效机制。</p><ul><li><code>Session</code> / <code>SessionStore</code>：记录每个打开文件的缓冲区权威状态——内容、文档版本、代次和服务状态——在 didOpen 时创建，在 didClose 时销毁。编译产物不存放在这里</li><li><code>ASTProjection</code> / <code>ASTProjectionTable</code>：每个文档最近一次编译所发布的产物（功能结果、PCH 键、依赖快照）——一种不可变的读取模型，每次发布时都会整体替换</li><li><code>Invalidator</code>：失效引擎——归并文件事件（缓冲区打开/保存、磁盘内容变化、编译数据库重新加载、worker 崩溃），生成一组去重的失效操作</li><li><code>FileTracker</code>：通过 stat 轮询发现编辑器之外发生的变化（重新生成 <code>compile_commands.json</code>、<code>git checkout</code>），并将事件送入 <code>Invalidator</code></li><li><code>Quarantine</code>：按文档统计崩溃——内容屡次导致 worker 崩溃的文档会被隔离，并通过获准的探测尝试恢复</li></ul><p><strong><code>service/</code></strong> — 使用编译和索引结果的读取侧服务。</p><ul><li><code>Features</code>：从各提供方——worker 的 AST、PCH 中缓存的 Preamble 产物或索引——组装各项功能的结果，并根据就绪状态路由每个请求：有最新 AST 时由 AST 响应，否则立即由索引支撑的投影响应。在 <code>readonly = on/auto</code> 下，文档完全由索引提供服务，直到编辑操作将其提升为完整的 AST 服务；编译始终按需进行，由请求而非生命周期事件触发</li><li><code>ASTFamily</code>：任务图中的文档 AST 节点族——调度打开文档的编译任务并发布结果</li><li><code>Dispatcher</code>：与 worker 通信的文档侧组件——每个携带打开文档内容的请求（有状态查询、交互式代码补全/签名帮助构建、格式化）都会先通过该文档的隔离检查，再进行分发，并统一经由一个出口返回；若客户端已修改该请求对应的缓冲区，则由该出口返回 <code>ContentModified</code></li><li><code>IndexQuery</code>：对所有索引来源——项目索引、按文件划分的分片以及打开文件的实时数据——执行只读查询，并统一仲裁数据时效性；以领域值作答，再由各传输层映射到各自的协议</li><li><code>ContextService</code>：编译上下文查询与切换的协议适配器</li></ul><p><strong><code>transport/</code></strong> — 驱动服务器的协议端点。</p><ul><li><code>MasterServer</code>：组合根。持有工作区、会话、工作线程池和上述所有服务，并通过自身唯一的分派入口执行 <code>Invalidator</code> 产生的操作</li><li><code>LSPClient</code> / <code>AgentClient</code>：LSP 协议和智能体协议的请求处理器</li></ul><p>详见 <a href="./multi-process">多进程架构</a>。</p><h3 id="src-driver-—-子命令" tabindex="-1"><code>src/driver/</code> — 子命令 <a class="header-anchor" href="#src-driver-—-子命令" aria-label="Permalink to &quot;`src/driver/` — 子命令&quot;">​</a></h3><p><code>clice</code> 二进制程序的入口点：<code>serve</code>（LSP 服务器）、<code>worker</code>、<code>index</code>（批量索引）、<code>lint</code>（批量 clang-tidy）、<code>inspect</code>、<code>format</code>、<code>query</code> 和 <code>doc</code>。</p><h2 id="模块间关系" tabindex="-1">模块间关系 <a class="header-anchor" href="#模块间关系" aria-label="Permalink to &quot;模块间关系&quot;">​</a></h2><p>数据流大致如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>command (structured compile commands)</span></span>\n<span class="line"><span>    ↓</span></span>\n<span class="line"><span>sched (task graph: PCH / PCM / AST / TU-run scheduling) ──→ worker (processes)</span></span>\n<span class="line"><span>    ↓ products</span></span>\n<span class="line"><span>compile (drives Clang compilation)</span></span>\n<span class="line"><span>    ↓</span></span>\n<span class="line"><span>semantic (semantic map) ──→ index (TUIndex / shards / ProjectIndex)</span></span>\n<span class="line"><span>    ↓</span></span>\n<span class="line"><span>feature (produces LSP responses)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>The server layer assembles all of the above via sessions, routing,</span></span>\n<span class="line"><span>invalidation, and transports into a runnable service.</span></span></code></pre></div><p><code>support</code>、<code>vfs</code>、<code>config</code> 和 <code>syntax</code> 是多个模块共享的横切层。</p>',56)])])}const m=o(i,[["render",r]]);export{u as __pageData,m as default};
